def transform(g):
    sep_rows=[i for i,row in enumerate(g) if len(set(row))==1 and row[0]==6]
    rg=[]; s=0
    for r in sep_rows+[len(g)]:
        if r>s: rg.append((s,r))
        s=r+1
    sep_cols=[c for c in range(len(g[0])) if all(row[c]==6 for row in g)]
    cg=[]; s=0
    for c in sep_cols+[len(g[0])]:
        if c>s: cg.append((s,c))
        s=c+1
    return [[1 if sum(g[r][c]==5 for r in range(a,b) for c in range(x,y))>=2 else 8 for x,y in cg] for a,b in rg]
